"""Generated by solo-to-scale; edit `templates/tools/goals.py` in the plugin, then run upgrade.

The company goal, its objectives and their key results, as data: founder/goals.json (founder-owned, behind the
`decision` gate). Slices, epics and stories name an objective with "objective": "O1"; tickets carry it as the
label `goal:O1` (`tickets.py new --objective O1`, inherited by sub-tickets).

  python tools/goals.py check                       # is goals.json well formed, and do the links point somewhere?
  python tools/goals.py show                        # the goal, each objective and its key results, with progress
  python tools/goals.py update O1.1 --value 42 [--date YYYY-MM-DD] [--note TEXT]
                                                    # record a key result's new value (commit it through a PR)

A key result's progress is how far `current` has moved from `baseline` towards `target`, from 0 to 100%; a
target below the baseline (cut churn from 8% to 3%) counts down. An objective's progress is the mean of its
key results. Python 3 standard library only.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import re
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402

FILE = "founder/goals.json"
OBJECTIVE_ID = re.compile(r"^O\d{1,3}$")
KR_ID = re.compile(r"^(O\d{1,3})\.\d{1,3}$")
STATUSES = ("planned", "active", "achieved", "cancelled")
LABEL_PREFIX = "goal:"
HISTORY_LIMIT = 60


def load(root: Path) -> dict[str, Any]:
    """goals.json as a dict; missing or unreadable means no goals yet."""
    try:
        data = json.loads(s.read(root / FILE) or "{}")
    except ValueError:
        return {"_error": f"{FILE} is not valid JSON"}
    return data if isinstance(data, dict) else {"_error": f"{FILE} must be a JSON object"}


def number(v: Any) -> float | None:
    if isinstance(v, bool) or v is None or v == "":
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def kr_progress(kr: dict[str, Any]) -> float | None:
    """0..1 from baseline to target, or None when the numbers aren't set."""
    base, target, cur = number(kr.get("baseline")), number(kr.get("target")), number(kr.get("current"))
    if target is None or cur is None:
        return None
    base = 0.0 if base is None else base
    if target == base:
        return 1.0 if cur == target else 0.0
    return max(0.0, min(1.0, (cur - base) / (target - base)))


def objectives(data: dict[str, Any]) -> list[dict[str, Any]]:
    return [o for o in data.get("objectives") or [] if isinstance(o, dict)]


def ids(data: dict[str, Any]) -> set[str]:
    return {str(o.get("id")) for o in objectives(data)}


def problems(root: Path, data: dict[str, Any] | None = None) -> list[str]:
    """Everything wrong with goals.json and the links to it; empty when it's fine or absent."""
    data = load(root) if data is None else data
    if "_error" in data:
        return [data["_error"]]
    out: list[str] = []
    seen: set[str] = set()
    for i, o in enumerate(data.get("objectives") or []):
        if not isinstance(o, dict):
            out.append(f"{FILE}: objective {i + 1} is not an object")
            continue
        oid = str(o.get("id") or "")
        where = f"{FILE}: objective {oid or i + 1}"
        if not OBJECTIVE_ID.match(oid):
            out.append(f"{where}: id must look like O1")
        elif oid in seen:
            out.append(f"{where}: id used twice")
        seen.add(oid)
        if not str(o.get("title") or "").strip():
            out.append(f"{where}: has no title")
        if o.get("status", "active") not in STATUSES:
            out.append(f"{where}: status must be one of {', '.join(STATUSES)}")
        if o.get("owner") and str(o["owner"]) not in (*s.ROLES, "chief-of-staff", "founder"):
            out.append(f"{where}: owner {o['owner']!r} is not a role")
        for kr in o.get("key_results") or []:
            kid = str((kr or {}).get("id") or "") if isinstance(kr, dict) else ""
            m = KR_ID.match(kid)
            if not m or m.group(1) != oid:
                out.append(f"{where}: key result id {kid or '?'} must look like {oid or 'O1'}.1")
                continue
            if kid in seen:
                out.append(f"{where}: key result {kid} used twice")
            seen.add(kid)
            if not str(kr.get("metric") or "").strip():
                out.append(f"{where}: key result {kid} has no metric")
            for k in ("baseline", "target", "current"):
                if kr.get(k) not in (None, "") and number(kr.get(k)) is None:
                    out.append(f"{where}: key result {kid} {k} must be a number")
            if number(kr.get("target")) is None:
                out.append(f"{where}: key result {kid} has no target")
    known = ids(data)
    cfg = s.config(root)
    sl = s.slices(root, cfg)
    things = [("epic", code, ep) for code, ep in sl["epics"].items() if isinstance(ep, dict)]
    things += [("slice", x.get("id"), x) for x in sl["slices"] if isinstance(x, dict)]
    things += [("story", x.get("id"), x) for x in sl["stories"] if isinstance(x, dict)]
    for kind, name, x in things:
        ref = x.get("objective")
        if ref and str(ref) not in known:
            out.append(f"{cfg.get('slices_file') or 'founder/slices.json'}: {kind} {name} names objective {ref}, "
                       f"which {FILE} doesn't define")
    return out


def active(data: dict[str, Any]) -> list[dict[str, Any]]:
    return [o for o in objectives(data) if o.get("status", "active") == "active"]


def build(root: Path) -> dict[str, Any]:
    """What the dashboard and the portfolio show: the goal, each objective with its progress and linked slices."""
    data = load(root)
    cfg = s.config(root)
    sl = s.slices(root, cfg)
    out_objs = []
    for o in objectives(data):
        krs = []
        for kr in o.get("key_results") or []:
            if not isinstance(kr, dict):
                continue
            hist = [h for h in kr.get("history") or [] if isinstance(h, dict) and number(h.get("value")) is not None]
            krs.append({"id": str(kr.get("id", "")), "metric": str(kr.get("metric", "")), "unit": str(kr.get("unit", "")),
                        "baseline": number(kr.get("baseline")), "target": number(kr.get("target")),
                        "current": number(kr.get("current")), "owner": str(kr.get("owner") or o.get("owner") or ""),
                        "updated": str(kr.get("updated", "")), "progress": kr_progress(kr),
                        "history": [{"date": str(h.get("date", "")), "value": number(h.get("value"))}
                                    for h in hist][-HISTORY_LIMIT:]})
        known = [k["progress"] for k in krs if k["progress"] is not None]
        oid = str(o.get("id", ""))
        linked = [x for x in sl["slices"] if isinstance(x, dict) and str(x.get("objective") or "") == oid]
        epics = sorted(code for code, ep in sl["epics"].items() if isinstance(ep, dict) and str(ep.get("objective") or "") == oid)
        out_objs.append({
            "id": oid, "title": str(o.get("title", "")), "quarter": str(o.get("quarter", "")),
            "owner": str(o.get("owner", "")), "status": str(o.get("status", "active")), "why": str(o.get("why", "")),
            "progress": round(sum(known) / len(known), 4) if known else None, "key_results": krs,
            "slices": {"total": len(linked), "done": sum(str(x.get("status", "")).lower() == "done" for x in linked),
                       "ids": [str(x.get("id", "")) for x in linked][:20]},
            "epics": epics,
        })
    return {"goal": str(data.get("goal") or ""), "horizon": str(data.get("horizon") or ""),
            "objectives": out_objs, "problems": problems(root, data)}


def label(objective: str) -> str:
    return LABEL_PREFIX + objective


def objective_of(labels: list[str]) -> str:
    return next((lb[len(LABEL_PREFIX):] for lb in labels if lb.startswith(LABEL_PREFIX)), "")


def pct(p: float | None) -> str:
    return "not measured yet" if p is None else f"{round(100 * p)}%"


def cmd_check(a: argparse.Namespace) -> int:
    found = problems(a.root)
    if found:
        print("\n".join(found))
        return 1
    data = load(a.root)
    print(f"goals: OK ({len(objectives(data))} objectives)" if data else f"goals: no {FILE} yet")
    return 0


def cmd_show(a: argparse.Namespace) -> int:
    g = build(a.root)
    print(f"Goal: {g['goal'] or 'Open (the founder sets it in ' + FILE + ')'}")
    for o in g["objectives"]:
        print(f"\n{o['id']} {o['title']} [{o['status']}{', ' + o['quarter'] if o['quarter'] else ''}] {pct(o['progress'])}")
        for k in o["key_results"]:
            print(f"  {k['id']} {k['metric']}: {k['current']} of {k['target']} {k['unit']} (from {k['baseline']}) {pct(k['progress'])}")
    for p in g["problems"]:
        print(f"problem: {p}")
    return 1 if g["problems"] else 0


def cmd_update(a: argparse.Namespace) -> int:
    data = load(a.root)
    if "_error" in data:
        raise SystemExit(data["_error"])
    date = a.date or dt.date.today().isoformat()
    try:
        dt.date.fromisoformat(date)
    except ValueError:
        raise SystemExit(f"--date {date!r} must be YYYY-MM-DD") from None
    for o in objectives(data):
        for kr in o.get("key_results") or []:
            if isinstance(kr, dict) and kr.get("id") == a.kr:
                kr["current"], kr["updated"] = a.value, date
                hist = [h for h in kr.get("history") or [] if isinstance(h, dict) and h.get("date") != date]
                hist.append({"date": date, "value": a.value, **({"note": a.note} if a.note else {})})
                kr["history"] = sorted(hist, key=lambda h: str(h.get("date")))[-HISTORY_LIMIT:]
                (a.root / FILE).write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8", newline="\n")
                print(f"{a.kr}: {a.value} on {date}. {FILE} is behind the decision gate: open a PR for the founder to merge.")
                return 0
    raise SystemExit(f"no key result {a.kr} in {FILE}")


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="The company goal, objectives and key results")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("check", parents=[common])
    sub.add_parser("show", parents=[common])
    u = sub.add_parser("update", parents=[common])
    u.add_argument("kr")
    u.add_argument("--value", type=float, required=True)
    u.add_argument("--date", default="")
    u.add_argument("--note", default="")
    a = ap.parse_args(argv)
    return {"check": cmd_check, "show": cmd_show, "update": cmd_update}[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
